def value(node):
    if isinstance(node,ast.Constant):return node.value
    if isinstance(node,ast.Dict):return {value(k):value(v)for k,v in zip(node.keys,node.values)}
    if isinstance(node,ast.List):return [value(x)for x in node.elts]
